CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  begin
    insert into public.profiles(id, full_name)
    values (
      new.id,
      coalesce(
        nullif(new.raw_user_meta_data->>'full_name', ''),
        nullif(new.raw_user_meta_data->>'name', ''),
        split_part(coalesce(new.email, 'CUSAT Student'), '@', 1)
      )
    )
    on conflict (id) do nothing;
  exception when others then
    raise warning 'handle_new_user profile side effect failed: %: %', sqlstate, sqlerrm;
  end;

  begin
    insert into public.user_roles(user_id, role)
    values (new.id, 'student'::public.user_role)
    on conflict (user_id, role) do nothing;
  exception when others then
    raise warning 'handle_new_user role side effect failed: %: %', sqlstate, sqlerrm;
  end;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_leaderboard_session(p_id uuid, p_ip_hash text, p_started_at timestamp with time zone, p_expires_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  recent_runs integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_ip_hash, 0));
  delete from public.leaderboard_sessions
    where started_at < pg_catalog.now() - interval '48 hours';
  select count(*) into recent_runs
    from public.leaderboard_sessions
    where ip_hash = p_ip_hash
      and started_at >= pg_catalog.now() - interval '1 hour';
  if recent_runs >= 60 then
    return false;
  end if;
  insert into public.leaderboard_sessions (id, ip_hash, started_at, expires_at)
    values (p_id, p_ip_hash, p_started_at, p_expires_at);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_leaderboard_run(p_run_id uuid, p_player_name text, p_score integer, p_distance_meters integer, p_blockades integer, p_elapsed_seconds integer, p_started_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  run_session public.leaderboard_sessions%rowtype;
begin
  select * into run_session
    from public.leaderboard_sessions
    where id = p_run_id
    for update;
  if not found or run_session.submitted_at is not null
     or run_session.expires_at <= pg_catalog.now()
     or abs(extract(epoch from (run_session.started_at - p_started_at))) > 2 then
    return false;
  end if;
  if p_elapsed_seconds < 1 or p_elapsed_seconds > 3600
     or p_score < 0 or p_score > least(2000000, p_elapsed_seconds * 85 + 100)
     or p_distance_meters < 0 or p_distance_meters > least(25000, ceil(p_elapsed_seconds * 7.2 + 3))
     or p_blockades < 0 or p_blockades > ceil(p_elapsed_seconds * 1.4 + 1)
     or char_length(p_player_name) < 1 or char_length(p_player_name) > 18 then
    return false;
  end if;
  insert into public.leaderboard
    (run_id, player_name, score, distance_meters, blockades, elapsed_seconds)
    values (p_run_id, p_player_name, p_score, p_distance_meters, p_blockades, p_elapsed_seconds);
  update public.leaderboard_sessions set submitted_at = pg_catalog.now() where id = p_run_id;
  return true;
end;
$function$
